  let T = J * W;

  // 3D 协方差矩阵 Vrk（对称矩阵）
  let Vrk = mat3x3f(
    cov3Da.x, cov3Da.y, cov3Da.z,
    cov3Da.y, cov3Db.x, cov3Db.y,
    cov3Da.z, cov3Db.y, cov3Db.z
  );

